package com.rikkeibank.transaction.service;import com.rikkeibank.common.api.BusinessException;import com.rikkeibank.transaction.client.AccountClient;import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Component;import java.math.BigDecimal;import java.util.UUID;
@Component public class AccountOperations{private final AccountClient client;private final String key;public AccountOperations(AccountClient c,@Value("${security.internal-key}")String k){client=c;key=k;}@CircuitBreaker(name="accountService",fallbackMethod="unavailable")public void debit(UUID op,UUID account,UUID customer,BigDecimal amount){client.debit(key,account,new AccountClient.Movement(op,customer,amount));}@CircuitBreaker(name="accountService",fallbackMethod="unavailable")public void credit(UUID op,UUID account,UUID customer,BigDecimal amount){client.credit(key,account,new AccountClient.Movement(op,customer,amount));}@CircuitBreaker(name="accountService",fallbackMethod="unavailable")public void refund(UUID op,UUID account,UUID customer,BigDecimal amount){client.refund(key,account,new AccountClient.Movement(op,customer,amount));}private void unavailable(UUID op,UUID account,UUID customer,BigDecimal amount,Throwable cause){throw new BusinessException(HttpStatus.SERVICE_UNAVAILABLE,"ACCOUNT_SERVICE_UNAVAILABLE","Account service unavailable: "+cause.getClass().getSimpleName());}}

